<script setup lang="ts">
import { redactSecrets } from '../config/snapshot-secrets.mjs';
import ActionIcon from './ActionIcon.vue';import { computed, ref } from 'vue';import InventoryFilters from './InventoryFilters.vue';import PageSummary from './PageSummary.vue';import DataGrid from './DataGrid.vue';import ResourceLink from './ResourceLink.vue';import { runningProcesses } from '../data/running-processes';import { contextMatches } from '../data/namespace-context';
const expanded=ref('');const search=ref(''),namespace=ref('__all__'),grouped=ref(false);const shown=computed(()=>runningProcesses.filter(p=>contextMatches(p.namespace)&&`${p.name} ${p.namespace} ${p.category} ${p.status}`.toLowerCase().includes(search.value.toLowerCase())));const groups=computed(()=>grouped.value?[...new Set(shown.value.map(p=>p.namespace))].sort().map(ns=>({namespace:ns,rows:shown.value.filter(p=>p.namespace===ns)})):[{namespace:'',rows:shown.value}]);
</script>
<template><section><PageSummary :count="shown.length" label="Processes" help="Submitted operations and affected resources appear here. Simulated preview processes are explicitly labeled; they do not apply changes to Kubernetes."/><InventoryFilters v-model:search="search" v-model:namespace="namespace" v-model:grouped="grouped" :namespaces="[]" search-label="Find A Process" placeholder="Name, namespace, operation, or status…"/><DataGrid><thead><tr><th>Process</th><th>Namespace</th><th>Operation</th><th>Status</th><th data-align="right">Progress</th><th>Started</th><th data-align="right">Resources</th><th>Actions</th></tr></thead><tbody><template v-for="group in groups" :key="group.namespace"><tr v-if="grouped"><th colspan="8">{{ group.namespace || 'Global' }}</th></tr><template v-for="process in group.rows" :key="process.id"><tr><td>{{ process.name }}</td><td><ResourceLink kind="Namespace" :name="process.namespace" :label="process.namespace || 'Global'"/></td><td>{{ process.category }}</td><td>{{ process.status }}</td><td :data-sort="process.progress"><progress :value="process.progress" max="100"/> {{ process.progress }}%</td><td :data-sort="process.startedAt">{{ new Date(process.startedAt).toLocaleString() }}</td><td>{{ process.resources.length }}</td><td class="actions-column"><button type="button" class="icon-action" :aria-label="`Review process ${process.name}`" :title="`Review ${process.name}`" @click="expanded=expanded===process.id?'':process.id"><ActionIcon icon="details"/></button></td></tr><tr v-if="expanded===process.id"><td colspan="8"><pre>{{ JSON.stringify(redactSecrets({resources:process.resources,configuration:process.configuration,receipt:process.receipt}), null, 2) }}</pre></td></tr></template></template></tbody></DataGrid></section></template>
<style scoped>table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:12px 8px;border-bottom:1px solid var(--border,#384352);text-align:left}pre{max-height:260px;overflow:auto;font-size:12px}progress{width:70px;accent-color:#71b5ff}</style>
